def inject_session(func: Callable) ->Callable:
    @wraps(func)
    def inner(ctx: click.Context, proxy_protocol: Optional[str]=None,
        proxy_host: Optional[str]=None, proxy_port: Optional[str]=None, key:
        Optional[str]=None, stage: Optional[Stage]=None, *args, **kwargs) ->Any:

        if not ctx:
            ctx = click.get_current_context()

        if not hasattr(ctx, 'obj'):
            ctx.obj = SafetyContext()

        if not hasattr(ctx.obj, 'auth'):
            ctx.obj.auth = type('Auth', (), {})()

