            session, proxy_config = build_client_session(
                api_key=key,
                proxies=get_proxy_dict(proxy_protocol, proxy_host, proxy_port),
                headers=None
            )
            ctx.obj.auth.client = session
            ctx.obj.auth.keys = get_keys(session)

        return func(ctx, *args, **kwargs)

